use semio_framework_test_original_snapshot_owners as original_owners;
#[test]
fn sqlite_snapshot_fem2d_declared_capability_is_owned() {
 let codec = semio_s_artifact_fem_2d_io::standards::v1::subsets::any::io::io().native.codec;
 assert!(codec.snapshot_sqlite.is_some(), "actual FEM2d declaration lacks its semantic SQLite provider");
}

use semio_s_artifact_fem_2d_model::standards::v1::subsets::any::schema::snapshot::{Fem2dSnapshot,Fem2dSnapshotValue};
use store::os_store::serialization::ArtifactSqliteSnapshotHost as _;
