fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn text(v:&serde_json::Value,key:&str)->String{v[key].as_str().unwrap().into()}
fn real(v:&serde_json::Value,key:&str)->f64{f64::from_bits(u64::from_str_radix(v[key].as_str().unwrap(),16).unwrap())}
fn point(v:&serde_json::Value)->[f64;2]{[f64::from_bits(u64::from_str_radix(v[0].as_str().unwrap(),16).unwrap()),f64::from_bits(u64::from_str_radix(v[1].as_str().unwrap(),16).unwrap())]}
fn dof(value:&str)->FemDof{match value{"Tx"=>FemDof::Tx,"Ty"=>FemDof::Ty,"Tz"=>FemDof::Tz,"Rx"=>FemDof::Rx,"Ry"=>FemDof::Ry,"Rz"=>FemDof::Rz,_=>panic!("fixture DOF")}}
fn state()->Fem2dSnapshotValue{
 let f=fixture();let s=&f["document"];
 Fem2dSnapshotValue{
  nodes:s["nodes"].as_array().unwrap().iter().map(|v|FemNodeValue{id:text(v,"id"),x:real(v,"xBits"),y:real(v,"yBits")}).collect(),
  elements:s["elements"].as_array().unwrap().iter().map(|v|{let(id,start,end,material_id,section_id)=(text(v,"id"),text(v,"start"),text(v,"end"),text(v,"materialId"),text(v,"sectionId"));match v["kind"].as_str().unwrap(){"bar"=>FemElement::Bar{id,start,end,material_id,section_id},"beam"=>FemElement::Beam{id,start,end,material_id,section_id},_=>panic!("fixture element")}}).collect(),
  regions:s["regions"].as_array().unwrap().iter().map(|v|FemRegion{id:text(v,"id"),name:text(v,"name"),outline:v["outlineBits"].as_array().unwrap().iter().map(point).collect(),holes:v["holesBits"].as_array().unwrap().iter().map(|h|h.as_array().unwrap().iter().map(point).collect()).collect(),thickness:real(v,"thicknessBits"),material_id:text(v,"materialId"),mesh_size:real(v,"meshSizeBits")}).collect(),
  materials:s["materials"].as_array().unwrap().iter().map(|v|FemMaterialValue{id:text(v,"id"),name:text(v,"name"),e:real(v,"eBits"),nu:real(v,"nuBits"),rho:real(v,"rhoBits")}).collect(),
  sections:s["sections"].as_array().unwrap().iter().map(|v|FemSection{id:text(v,"id"),name:text(v,"name"),area:real(v,"areaBits"),iy:real(v,"iyBits")}).collect(),
  supports:s["supports"].as_array().unwrap().iter().map(|v|FemSupport{id:text(v,"id"),node_id:text(v,"nodeId"),fixed:v["fixed"].as_array().unwrap().iter().map(|x|dof(x.as_str().unwrap())).collect()}).collect(),
  load_cases:s["loadCases"].as_array().unwrap().iter().map(|v|FemLoadCase{id:text(v,"id"),name:text(v,"name"),self_weight:v["selfWeight"].as_bool().unwrap(),loads:v["loads"].as_array().unwrap().iter().map(|x|match x["kind"].as_str().unwrap(){"nodal"=>FemLoad::Nodal{id:text(x,"id"),node_id:text(x,"nodeId"),dof:dof(x["dof"].as_str().unwrap()),value:real(x,"valueBits")},"memberUdl"=>FemLoad::MemberUdl{id:text(x,"id"),element_id:text(x,"elementId"),wx:real(x,"wxBits"),wy:real(x,"wyBits")},"area"=>FemLoad::Area{id:text(x,"id"),region_id:text(x,"regionId"),pressure:real(x,"pressureBits")},_=>panic!("fixture load")}).collect()}).collect(),
  combinations:s["combinations"].as_array().unwrap().iter().map(|v|FemCombination{id:text(v,"id"),name:text(v,"name"),terms:v["terms"].as_array().unwrap().iter().map(|x|FemCombinationTerm{case_id:text(x,"caseId"),factor:real(x,"factorBits")}).collect()}).collect(),
  analysis:FemAnalysisSettings{modal_count:s["analysis"]["modalCount"].as_str().unwrap().parse().unwrap(),buckling_count:s["analysis"]["bucklingCount"].as_str().unwrap().parse().unwrap(),deformation_scale:real(&s["analysis"],"deformationScaleBits")}
 }
}
struct Own(Option<Fem2dSnapshot>);
impl Own{fn new(value:Fem2dSnapshot)->Self{Self(Some(value))}fn get(&self)->&Fem2dSnapshot{self.0.as_ref().unwrap()}}
impl std::ops::Deref for Own{type Target=Fem2dSnapshot;fn deref(&self)->&Fem2dSnapshot{self.get()}}
impl Drop for Own{fn drop(&mut self){if let Some(value)=self.0.take(){<Fem2dSnapshot as store::os_store::serialization::ArtifactSqliteSnapshotHost>::retire_sqlite_snapshot(value);}}}
fn own(v:&Fem2dSnapshotValue)->Own{Own::new(Fem2dSnapshot::from_reference(v.clone()).unwrap())}
fn project_native(s:&Fem2dSnapshot)->SqliteDatabase{original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|true,|sqlite_control|s.to_sqlite_database(sqlite_control)).unwrap()}
fn project(s:&Fem2dSnapshotValue)->SqliteDatabase{project_native(&own(s))}
fn restore(d:&SqliteDatabase)->Result<Own,semio_framework_value::ValueError>{original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|true,|sqlite_control|Fem2dSnapshot::from_sqlite_database(d, sqlite_control)).map(Own::new)}
fn every_word(s:&mut Fem2dSnapshotValue,word:u64){let v=f64::from_bits(word);s.analysis.deformation_scale=v;for n in &mut s.nodes{if v.is_finite(){n.x=v;n.y=v;}}for r in &mut s.regions{r.thickness=v;r.mesh_size=v;for p in &mut r.outline{*p=[v,v];}for h in &mut r.holes{for p in h{*p=[v,v];}}}for m in &mut s.materials{if v.is_finite()&&v>0.{m.e=v;m.rho=v;}if v>-1.&&v<0.5{m.nu=v;}}for x in &mut s.sections{if v.is_finite()&&v>0.{x.area=v;x.iy=v;}}for c in &mut s.load_cases{for x in &mut c.loads{match x{FemLoad::Nodal{value,..}=>if v.is_finite(){*value=v},FemLoad::MemberUdl{wx,wy,..}=>if v.is_finite(){*wx=v;*wy=v;},FemLoad::Area{pressure,..}=>if v.is_finite(){*pressure=v}}}}for c in &mut s.combinations{for x in &mut c.terms{x.factor=v;}}}
#[test]fn sqlite_snapshot_fem2d_complete_physical_state(){let source=state();let d=project(&source);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let imported=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(project_native(&restore(&imported).unwrap()),d);assert!(restore(&d).unwrap().regions[0].holes[0].is_empty());for(name,count)in fixture()["tableRowCounts"].as_object().unwrap(){assert_eq!(d.table(name).unwrap().rows.len(),count.as_u64().unwrap()as usize);}}
#[test]fn sqlite_snapshot_fem2d_independent_bun_file_queries_and_edits(){use std::io::Write;use std::process::{Command,Stdio};let d=project(&state());let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT COUNT(*) AS n FROM sqlite_schema WHERE type=\'table\'').get().n!==18n)throw Error('table count');if(d.query('SELECT authored_id FROM fem2d_node WHERE id=1').get().authored_id!==JSON.parse('@ID@'))throw Error('literal');d.query('UPDATE fem2d_material SET name=? WHERE id=1').run('edited 日本\u0000');await Bun.write(Bun.stdout,d.serialize());d.close();"#;let mut child=Command::new("bun").args(["-e",&script.replace("@ID@",&serde_json::to_string(&fixture()["document"]["nodes"][0]["id"]).unwrap())]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let s=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(s.materials[0].name.as_str(),"edited 日本\0");assert!(s.regions[0].holes[0].is_empty());}
#[test]fn sqlite_snapshot_fem2d_all_words_and_count_widths(){for word in fixture()["ieee754Words"].as_array().unwrap(){let mut s=state();every_word(&mut s,u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let d=project(&s);assert_eq!(project_native(&restore(&d).unwrap()),d);}for word in fixture()["countWords"].as_array().unwrap(){let mut s=state();s.analysis.modal_count=word.as_str().unwrap().parse().unwrap();s.analysis.buckling_count=s.analysis.modal_count;let d=project(&s);assert_eq!(project_native(&restore(&d).unwrap()),d);}}
#[test]fn sqlite_snapshot_fem2d_invalid_graph_and_storage(){let source=project(&state());for n in 0..10{let mut d=source.clone();match n{0=>d.table_mut("fem2d_node").unwrap().rows[1].values[2]=SqliteValue::Integer(5),1=>d.table_mut("fem2d_hole_vertex").unwrap().rows[0].values[1]=SqliteValue::Integer(999),2=>d.table_mut("fem2d_nodal_load").unwrap().rows.clear(),3=>{let r=&mut d.table_mut("fem2d_nodal_load").unwrap().rows[0];r.rowid=2;r.values[0]=SqliteValue::Integer(2);},4=>d.table_mut("fem2d_support_dof").unwrap().rows[0].values[3]=SqliteValue::Text("bad".into()),5=>d.table_mut("fem2d_document").unwrap().rows[0].values[1]=SqliteValue::Text("18446744073709551616".into()),6=>d.table_mut("fem2d_document").unwrap().rows[0].values[2]=SqliteValue::Text("01".into()),7=>d.table_mut("fem2d_node").unwrap().rows[0].values[6]=SqliteValue::Integer(0x3ff0000000000000),8=>d.table_mut("fem2d_node").unwrap().rows[0].values[3]=SqliteValue::Integer(17),_=>{let t=d.table_mut("fem2d_element").unwrap();t.sql=t.sql.replacen("TEXT NOT NULL","TEXT \"NOT\" \"NULL\"",1);}}assert!(restore(&d).is_err(),"case{n}");}}
#[test]fn sqlite_snapshot_fem2d_actual_declaration_erased_words_both_encodings(){let codec=semio_s_artifact_fem_2d_io::standards::v1::subsets::any::io::io().native.codec;let schema=codec.schema.clone();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.fem.fem2d".into(),standard:"1".into(),subset:"*".into()};for word in fixture()["ieee754Words"].as_array().unwrap(){let word=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();if !f64::from_bits(word).is_finite(){continue}let mut s=state();every_word(&mut s,word);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&*own(&s))),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&*own(&s)))};let d=original_owners::export_sqlite(provider,&schema,&dialect,&expected,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(project_native(&restore(&d).unwrap()),project(&s));let actual=original_owners::import_sqlite(provider,&schema,&dialect,d,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,expected);}}}
#[test]fn sqlite_snapshot_fem2d_real_interior_copy_controls_and_budgets(){let mut s=state();s.materials[0].name="日本🧬".repeat(32768);let o=own(&s);let d=project_native(&o);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{let mut interior=false;let mut cb=|p:SqliteSnapshotProgress|{if p.phase==phase&&p.completed>=65536&&p.completed<p.total{interior=true;false}else{true}};let mut c=SqliteSnapshotControl::new(&mut cb,SqliteDatabaseLimits::default());let result=match phase{SqliteSnapshotPhase::ProjectSnapshot=>o.to_sqlite_database(&mut c).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>Fem2dSnapshot::from_sqlite_database(&d,&mut c).map(Own::new).is_err(),_=>original_owners::encode_native(&*o,SnapshotEncoding::Text,&mut c).is_err()};assert!(result);assert!(interior);}let mut accept=|_|true;assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()},&mut accept,|sqlite_control|o.to_sqlite_database(sqlite_control)).is_err());assert!(original_owners::encode_native(&*o,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());assert!(original_owners::encode_native(&*o,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1024,..SqliteDatabaseLimits::default()})).is_err());}
#[test]fn sqlite_snapshot_fem2d_native_decode_actual_interior_owned_work(){let mut s=state();s.nodes.extend((0..2048).map(|n|FemNodeValue{id:format!("bulk{n}"),x:0.,y:0.}));for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&*own(&s))),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&*own(&s)))};let mut interior=false;let mut cb=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.completed>=256&&p.completed<p.total{interior=true;false}else{true}};assert!(original_owners::decode_native::<Fem2dSnapshot>(&payload,&mut SqliteSnapshotControl::new(&mut cb,SqliteDatabaseLimits::default())).is_err());assert!(interior);assert!(original_owners::decode_native::<Fem2dSnapshot>(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1024,..SqliteDatabaseLimits::default()})).is_err());}}
